CREATE OR REPLACE FUNCTION public.platform_settings_validate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.key = 'commission_rate_percent' and not (jsonb_typeof(new.value) = 'number' and (new.value #>> '{}')::numeric between 0 and 50) then
    raise exception 'invalid_setting: commission_rate_percent must be a number between 0 and 50' using errcode = 'P0001';
  elsif new.key = 'commission_base' and not (jsonb_typeof(new.value) = 'string' and new.value #>> '{}' in ('accommodation', 'accommodation_and_cleaning')) then
    raise exception 'invalid_setting: commission_base' using errcode = 'P0001';
  elsif new.key in ('commission_reverse_on_cancellation', 'refund_reverses_commission', 'settlement_requires_payment') and jsonb_typeof(new.value) <> 'boolean' then
    raise exception 'invalid_setting: % must be true or false', new.key using errcode = 'P0001';
  end if;
  return new;
end $function$;
do $storage$ begin
  if to_regclass('storage.objects') is not null then
    execute 'drop policy if exists "product images are public" on storage.objects';
    execute 'drop policy if exists "providers delete service images" on storage.objects';
    execute 'drop policy if exists "providers upload service images" on storage.objects';
    execute 'drop policy if exists "sellers delete product images" on storage.objects';
    execute 'drop policy if exists "sellers upload product images" on storage.objects';
    execute 'drop policy if exists "service images are public" on storage.objects';
    execute 'drop policy if exists "vendors delete own documents" on storage.objects';
    execute 'drop policy if exists "vendors read own documents, admins read all" on storage.objects';
    execute 'drop policy if exists "vendors upload own documents" on storage.objects';
  end if;
end $storage$;
